3	namespace App\Services\Media;
4	
5	use App\Models\Core\MediaVariant;
6	use App\Models\Core\Site\SiteMedia;
7	use Illuminate\Support\Facades\Log;
8	use Illuminate\Support\Facades\Storage;
9	use Symfony\Component\Process\Process;
10	
11	/**
12	 * Transcodes a video original into MP4 + HLS variants and a poster image,
13	 * stores all artifacts on the media disk, and persists MediaVariant rows.
14	 *
15	 * Processing order (avoids extra re-encodes):
16	 *   1. FFprobe  – extract metadata + validate duration
17	 *   2. FFmpeg   – encode optimized MP4 (720p)
18	 *   3. FFmpeg   – encode maximized MP4 (1080p)
19	 *   4. FFmpeg   – package HLS segments from each MP4 (stream-copy, no re-encode)
20	 *   5. Build    – write master adaptive HLS playlist
21	 *   6. FFmpeg   – extract poster JPEG at 1s mark
22	 *   7. Upload   – stream all artifacts to media disk
23	 *   8. DB upsert – persist one MediaVariant row per logical artifact
24	 *   9. SiteMedia update – set processing_state, duration_ms, poster_path
25	 *
26	 * Storage layout under the media disk:
27	 *   videos/{proId}/{mediaId}/
28	 *     original_{hash}.{ext}
29	 *     optimized.mp4
30	 *     maximized.mp4
31	 *     hls/
32	 *       optimized/playlist.m3u8  + seg_*.ts
33	 *       maximized/playlist.m3u8  + seg_*.ts
34	 *       adaptive.m3u8             (master playlist)
35	 *     poster.jpg
36	 *
37	 * Requires ffmpeg and ffprobe to be available (configured via config/sidest.php).
38	 */
39	// V2: Transcodes videos to MP4 + HLS via FFmpeg. Feature-flagged (SIDEST_VIDEO_UPLOADS_ENABLED). Uses dedicated redis_video connection.
40	class VideoVariantService
41	{
42	    /** Codecs we will transcode. hevc = H.265 (ffprobe reports 'hevc', not 'h265'). */
43	    private const ALLOWED_CODECS = ['h264', 'hevc', 'vp9'];
44	
45	    /** 4K ceiling: long edge ≤ 3840px, short edge ≤ 2160px. */
46	    private const MAX_RESOLUTION_LONG = 3840;
47	    private const MAX_RESOLUTION_SHORT = 2160;
48	
49	    /* ------------------------------------------------------------------ */
50	    /*  Public API */
51	    /* ------------------------------------------------------------------ */
52	
53	    /**
54	     * Run FFprobe on a local file and return metadata array.
55	     * Throws \RuntimeException if the binary fails.
56	     *
57	     * @return array<string, mixed>
58	     */
59	    public function probe(string $localPath): array
60	    {
61	        $ffprobe = $this->ffprobeBinary();
62	
63	        $process = new Process([
64	            $ffprobe, '-v', 'quiet', '-print_format', 'json',
65	            '-show_format', '-show_streams', $localPath,
66	        ]);
67	        $process->setTimeout(30);
68	        $process->run();
69	
70	        if (! $process->isSuccessful()) {
71	            $exitCode = $process->getExitCode();
72	            $err = $process->getErrorOutput() ?: $process->getOutput();
73	            throw new \RuntimeException("ffprobe failed (exit {$exitCode}): {$err}");
74	        }
75	
76	        $data = json_decode($process->getOutput(), true);
77	        if (! is_array($data)) {
78	            throw new \RuntimeException('ffprobe returned non-JSON output.');
79	        }
80	
81	        return $data;
82	    }
83	
84	    /**
85	     * Probe a local file and validate it contains at least one video stream
86	     * and does not exceed the configured maximum duration.
87	     *
88	     * Call this in the upload controller before storing to R2 so malformed
89	     * containers and over-length videos are rejected at the HTTP boundary,
90	     * not on the worker.
91	     *
92	     * @return array<string, mixed> Raw ffprobe data (reuse to avoid a second probe).
93	     * @throws \RuntimeException if the container is unreadable, has no video stream, or exceeds max duration.
94	     */
95	    public function probeAndValidate(string $localPath): array
96	    {
97	        $probe = $this->probe($localPath);
98	
99	        $videoStream = null;
100	        foreach ($probe['streams'] ?? [] as $stream) {
101	            if (($stream['codec_type'] ?? '') === 'video') {
102	                $videoStream = $stream;
103	                break;
104	            }
105	        }
106	
107	        if ($videoStream === null) {
108	            throw new \RuntimeException('File does not contain a recognisable video stream.');
109	        }
110	
111	        $codec = strtolower((string) ($videoStream['codec_name'] ?? ''));
112	        if (! in_array($codec, self::ALLOWED_CODECS, true)) {
113	            throw new \RuntimeException(
114	                "Unsupported video codec '{$codec}'. Allowed: ".implode(', ', self::ALLOWED_CODECS).'.'
115	            );
116	        }
117	
118	        $width = (int) ($videoStream['width'] ?? 0);
119	        $height = (int) ($videoStream['height'] ?? 0);
120	        $longEdge = max($width, $height);
121	        $shortEdge = min($width, $height);
122	        if ($longEdge > self::MAX_RESOLUTION_LONG || $shortEdge > self::MAX_RESOLUTION_SHORT) {
123	            throw new \RuntimeException(
124	                "Video resolution {$width}×{$height} exceeds the maximum allowed (3840×2160 / 4K)."
125	            );
126	        }
127	
128	        $durationMs = $this->extractDurationMs($probe);
129	        $maxDurSec = (int) config('sidest.video_max_duration_seconds', 300);
130	
131	        if ($durationMs > $maxDurSec * 1000) {
132	            $actualSec = (int) round($durationMs / 1000);
133	            throw new \RuntimeException(
134	                "Video is too long ({$actualSec}s). Maximum allowed duration is {$maxDurSec}s."
135	            );
136	        }
137	
138	        return $probe;
139	    }
140	
141	    /**
142	     * Process a video original into all configured artifacts.
143	     *
144	     * @throws \RuntimeException on unrecoverable processing errors
145	     */
146	    public function processVariants(
147	        string $localOriginalPath,
148	        string $mediaId,
149	        string $basePath,
150	    ): void {
151	        Log::info('VideoVariantService: starting', [
152	            'media_id' => $mediaId,
153	            'base_path' => $basePath,
154	        ]);
155	
156	        // --- 1. Probe metadata + validate codec, resolution, and duration ---
157	        $probe = $this->probeAndValidate($localOriginalPath);
158	        $durationMs = $this->extractDurationMs($probe);
159	
160	        // Timeout budget: 2× video duration + 60s, floored at 120s for very short clips.
161	        $encodingTimeout = max(120, (int) round($durationMs / 1000) * 2 + 60);
162	
163	        $variantDefs = (array) config('sidest.video_variants', []);
164	        $tmpDirs = [];
165	
166	        try {
167	            // --- 2 & 3. Encode MP4 variants ---
168	            $mp4Paths = [];
169	            foreach ($variantDefs as $variantKey => $def) {
170	                $tmpMp4 = $this->makeTmpFile("sidest_mp4_{$variantKey}_", '.mp4');
171	                $this->encodeMp4($localOriginalPath, $tmpMp4, $def, $encodingTimeout);
172	                $mp4Paths[$variantKey] = $tmpMp4;
173	            }
174	
175	            // --- 4. Package HLS from each MP4 ---
176	            $hlsDirs = [];
177	            foreach ($mp4Paths as $variantKey => $mp4) {
178	                $tmpHlsDir = sys_get_temp_dir().'/sidest_hls_'.$variantKey.'_'.uniqid();
179	                if (! mkdir($tmpHlsDir, 0755, true)) {
180	                    throw new \RuntimeException("Failed to create HLS temp dir: {$tmpHlsDir}");
181	                }
182	                $tmpDirs[] = $tmpHlsDir;
183	                $this->packageHls($mp4, $tmpHlsDir.'/playlist.m3u8', $encodingTimeout);
184	                $hlsDirs[$variantKey] = $tmpHlsDir;
185	            }
186	
187	            // --- 5. Build adaptive master playlist ---
188	            $adaptiveContent = $this->buildAdaptivePlaylist($variantDefs);
189	
190	            // --- 6. Extract poster ---
191	            $tmpPoster = $this->makeTmpFile('sidest_poster_', '.jpg');
192	            $this->extractPoster($localOriginalPath, $tmpPoster, $encodingTimeout);
193	
194	            // --- 7. Upload all artifacts ---
195	            $disk = $this->disk();
196	            $diskName = $this->resolvedDiskName();
197	
198	            // Upload MP4s
199	            foreach ($mp4Paths as $variantKey => $mp4) {
200	                $remotePath = "{$basePath}/{$variantKey}.mp4";
201	                $stream = fopen($mp4, 'rb');
202	                $disk->put($remotePath, $stream, 'public');
203	                if (is_resource($stream)) {
204	                    fclose($stream);
205	                }
206	
207	                $def = $variantDefs[$variantKey] ?? [];
208	                // Unique key: (media_id, variant_key, artifact_type)
209	                MediaVariant::updateOrCreate(
210	                    ['media_id' => $mediaId, 'variant_key' => $variantKey, 'artifact_type' => 'mp4'],
211	                    [
212	                        'disk' => $diskName,
213	                        'path' => $remotePath,
214	                        'mime' => 'video/mp4',
215	                        'bitrate_kbps' => (int) ($def['video_bitrate_kbps'] ?? 0) + (int) ($def['audio_bitrate_kbps'] ?? 0),
216	                        'file_size_bytes' => filesize($mp4) ?: null,
217	                        'duration_ms' => $durationMs,
218	                        'metadata' => ['resolution' => $def['resolution'] ?? null],
219	                    ]
220	                );
221	            }
222	
223	            // Upload HLS segments + playlists
224	            foreach ($hlsDirs as $variantKey => $hlsDir) {
225	                $remoteHlsBase = "{$basePath}/hls/{$variantKey}";
226	                foreach (scandir($hlsDir) ?: [] as $file) {
227	                    if ($file === '.' || $file === '..') {
228	                        continue;
229	                    }
230	                    $localFile = "{$hlsDir}/{$file}";
231	                    $remotePath = "{$remoteHlsBase}/{$file}";
232	                    $mime = str_ends_with($file, '.m3u8') ? 'application/vnd.apple.mpegurl' : 'video/mp2t';
233	                    $stream = fopen($localFile, 'rb');
234	                    $disk->put($remotePath, $stream, ['visibility' => 'public', 'ContentType' => $mime]);
235	                    if (is_resource($stream)) {
236	                        fclose($stream);
237	                    }
238	                }
239	
240	                $playlistPath = "{$remoteHlsBase}/playlist.m3u8";
241	                $def = $variantDefs[$variantKey] ?? [];
242	                MediaVariant::updateOrCreate(
243	                    ['media_id' => $mediaId, 'variant_key' => $variantKey, 'artifact_type' => 'hls_playlist'],
244	                    [
245	                        'disk' => $diskName,
246	                        'path' => $playlistPath,
247	                        'mime' => 'application/vnd.apple.mpegurl',
248	                        'duration_ms' => $durationMs,
249	                        'metadata' => ['resolution' => $def['resolution'] ?? null],
250	                    ]
251	                );
252	            }
253	
254	            // Upload adaptive master playlist
255	            $adaptiveRemotePath = "{$basePath}/hls/adaptive.m3u8";
256	            $disk->put($adaptiveRemotePath, $adaptiveContent, [
257	                'visibility' => 'public',
258	                'ContentType' => 'application/vnd.apple.mpegurl',
259	            ]);
260	
261	            MediaVariant::updateOrCreate(
262	                ['media_id' => $mediaId, 'variant_key' => 'adaptive', 'artifact_type' => 'hls_playlist'],
263	                [
264	                    'disk' => $diskName,
265	                    'path' => $adaptiveRemotePath,
266	                    'mime' => 'application/vnd.apple.mpegurl',
267	                ]
268	            );
269	
270	            // Upload poster
271	            $posterRemotePath = "{$basePath}/poster.jpg";
272	            $stream = fopen($tmpPoster, 'rb');
273	            $disk->put($posterRemotePath, $stream, ['visibility' => 'public', 'ContentType' => 'image/jpeg']);
274	            if (is_resource($stream)) {
275	                fclose($stream);
276	            }
277	
278	            MediaVariant::updateOrCreate(
279	                ['media_id' => $mediaId, 'variant_key' => 'poster', 'artifact_type' => 'poster'],
280	                [
281	                    'disk' => $diskName,
282	                    'path' => $posterRemotePath,
283	                    'mime' => 'image/jpeg',
284	                    'file_size_bytes' => filesize($tmpPoster) ?: null,
285	                ]
286	            );
287	
288	            // --- 8. Update SiteMedia ---
289	            SiteMedia::query()
290	                ->where('id', $mediaId)
291	                ->whereNull('deleted_at')
292	                ->update([
293	                    'processing_state' => SiteMedia::PROCESSING_STATE_READY,
294	                    'processing_error' => null,
295	                    'duration_ms' => $durationMs,
296	                    'poster_path' => $posterRemotePath,
297	                ]);
298	
299	            Log::info('VideoVariantService: completed', [
300	                'media_id' => $mediaId,
301	                'duration_ms' => $durationMs,
302	            ]);
303	        } finally {
304	            // Cleanup temp files and dirs
305	            foreach ($mp4Paths ?? [] as $mp4) {
306	                if (file_exists($mp4)) {
307	                    @unlink($mp4);
308	                }
309	            }
