425	    private function extractPoster(string $input, string $output, int $timeout): void
426	    {
427	        $ffmpeg = $this->ffmpegBinary();
428	
429	        $cmd = [$ffmpeg, '-y', '-i', $input, '-ss', '00:00:01', '-frames:v', '1', '-q:v', '3', $output];
430	        $outputStr = $this->runCommand($cmd, $exitCode, $timeout);
431	
432	        if ($exitCode !== 0 || ! file_exists($output)) {
433	            // Non-fatal: try frame at 0s as fallback
434	            $cmd2 = [$ffmpeg, '-y', '-i', $input, '-frames:v', '1', '-q:v', '3', $output];
435	            $this->runCommand($cmd2, $exitCode2, $timeout);
436	
437	            if ($exitCode2 !== 0 || ! file_exists($output)) {
438	                Log::warning('VideoVariantService: could not extract poster frame; writing placeholder JPEG.', [
439	                    'error' => $outputStr,
440	                ]);
441	
442	                if (! $this->writePlaceholderJpeg($output)) {
443	                    throw new \RuntimeException('Could not extract poster frame and GD is unavailable to generate a placeholder.');
444	                }
445	            }
446	        }
447	    }
