449	    /**
450	     * Write a minimal 1×1 black JPEG to $path as a last-resort poster placeholder.
451	     * Returns false if the GD extension is not loaded.
452	     */
453	    private function writePlaceholderJpeg(string $path): bool
454	    {
455	        if (! function_exists('imagecreatetruecolor')) {
456	            return false;
457	        }
458	
459	        $img = imagecreatetruecolor(1, 1);
460	        if ($img === false) {
461	            return false;
462	        }
463	
464	        $written = imagejpeg($img, $path, 85);
465	        imagedestroy($img);
466	
467	        return $written;
468	    }
