470	    /**
471	     * Build the adaptive (master) HLS playlist content.
472	     *
473	     * @param  array<string, array<string, mixed>>  $variantDefs
474	     */
475	    private function buildAdaptivePlaylist(array $variantDefs): string
476	    {
477	        $lines = ['#EXTM3U'];
478	
479	        foreach ($variantDefs as $variantKey => $def) {
480	            // Guard against config values containing newlines or special chars
481	            // that would corrupt the line-based M3U8 format.
482	            if (! preg_match('/^[a-zA-Z0-9_-]+$/', (string) $variantKey)) {
483	                throw new \RuntimeException("Invalid video variant key: {$variantKey}");
484	            }
485	
486	            $videoBitrate = (int) ($def['video_bitrate_kbps'] ?? 2000);
487	            $audioBitrate = (int) ($def['audio_bitrate_kbps'] ?? 128);
488	            $bandwidth = ($videoBitrate + $audioBitrate) * 1000;
489	            $resolution = strtoupper((string) ($def['resolution'] ?? '1280x720'));
490	
491	            // Resolution must be WxH (digits only) — e.g. 1280x720, 1920X1080.
492	            if (! preg_match('/^\d+X\d+$/', $resolution)) {
493	                throw new \RuntimeException("Invalid video resolution for variant '{$variantKey}': {$resolution}");
494	            }
495	
496	            $lines[] = "#EXT-X-STREAM-INF:BANDWIDTH={$bandwidth},RESOLUTION={$resolution}";
497	            $lines[] = "{$variantKey}/playlist.m3u8";
498	        }
499	
500	        return implode("\n", $lines)."\n";
501	    }
