503	    private function extractDurationMs(array $probe): int
504	    {
505	        $duration = $probe['format']['duration'] ?? null;
506	        if ($duration === null) {
507	            // Fall back to the first video stream
508	            foreach ($probe['streams'] ?? [] as $stream) {
509	                if (($stream['codec_type'] ?? '') === 'video' && isset($stream['duration'])) {
510	                    $duration = $stream['duration'];
511	                    break;
512	                }
513	            }
514	        }
515	
516	        return $duration !== null ? (int) round((float) $duration * 1000) : 0;
517	    }
