519	    private function makeTmpFile(string $prefix, string $suffix): string
520	    {
521	        $path = tempnam(sys_get_temp_dir(), $prefix);
522	        if (! $path) {
523	            throw new \RuntimeException("Failed to create temp file ({$prefix}).");
524	        }
525	
526	        // Rename to add the desired extension so FFmpeg knows the container.
527	        $withExt = $path.$suffix;
528	        rename($path, $withExt);
529	
530	        return $withExt;
531	    }
