533	    /**
534	     * Run an FFmpeg/FFprobe command via Symfony Process and return combined stdout+stderr.
535	     * $exitCode is set by reference.
536	     *
537	     * Uses array-form Process — each element is passed as a literal argument,
538	     * bypassing the shell entirely and eliminating injection via argument composition.
539	     */
540	    private function runCommand(array $cmd, ?int &$exitCode = null, int $timeout = 30): string
541	    {
542	        $process = new Process($cmd);
543	        $process->setTimeout($timeout);
544	        $process->run();
545	
546	        $exitCode = $process->getExitCode() ?? 0;
547	
548	        return $process->getOutput() . $process->getErrorOutput();
549	    }
