551	    private function removeDir(string $dir): void
552	    {
553	        if (! is_dir($dir)) {
554	            return;
555	        }
556	
557	        foreach (scandir($dir) ?: [] as $file) {
558	            if ($file === '.' || $file === '..') {
559	                continue;
560	            }
561	            $path = "{$dir}/{$file}";
562	            is_dir($path) ? $this->removeDir($path) : @unlink($path);
563	        }
564	
565	        @rmdir($dir);
566	    }
