568	    /**
569	     * Legacy jobs may pass the original file path instead of the media directory.
570	     * Normalize to the directory prefix expected by allFiles().
571	     */
572	    private function normalizeVideoCleanupBasePath(string $basePath): string
573	    {
574	        $normalized = trim($basePath);
575	        if ($normalized === '') {
576	            throw new \RuntimeException('Video cleanup base path cannot be empty.');
577	        }
578	
579	        $leaf = basename($normalized);
580	        if (str_contains($leaf, '.')) {
581	            $normalized = dirname($normalized);
582	        }
583	
584	        $normalized = trim($normalized, '/');
585	        if ($normalized === '' || $normalized === '.') {
586	            throw new \RuntimeException('Video cleanup base path resolved to an invalid directory.');
587	        }
588	
589	        return $normalized;
590	    }
