592	    private function diskName(): string
593	    {
594	        $configured = (string) config('sidest.media_disk', 'media');
595	
596	        // $_ENV/$_SERVER are intentional here — Laravel Cloud caches config at deploy time
597	        // but injects platform env vars directly into the process environment at runtime,
598	        // so env()/config() won't see them. Direct superglobal access bypasses that cache.
599	        $explicit = $_ENV['SIDEST_MEDIA_DISK'] ?? $_SERVER['SIDEST_MEDIA_DISK'] ?? null;
600	        if (is_string($explicit) && trim($explicit) !== '') {
601	            return $configured;
602	        }
603	
604	        if ($configured === 'media') {
605	            $default = (string) config('filesystems.default', 'local');
606	            $defaultConfig = config("filesystems.disks.{$default}");
607	
608	            if (
609	                $default !== '' &&
610	                $default !== 'local' &&
611	                $default !== 'media' &&
612	                is_array($defaultConfig) &&
613	                (($defaultConfig['driver'] ?? null) === 's3')
614	            ) {
615	                return $default;
616	            }
617	        }
618	
619	        return $configured;
620	    }
